import UIKit

class TapHelper {
    static func tapOpenButton() {
        // Get the key window
        guard let window = UIApplication.shared.connectedScenes
            .compactMap({ $0 as? UIWindowScene })
            .first?.windows.first(where: { $0.isKeyWindow }) else {
            print("Window not found")
            return
        }

        // Find the Open button in the view hierarchy
        if let openButton = findButton(in: window.rootViewController?.view, withTitle: "Open") {
            openButton.sendActions(for: .touchUpInside)
            print("Tapped Open button")
        } else {
            print("Open button not found")
        }
    }

    static func findButton(in view: UIView?, withTitle title: String) -> UIButton? {
        guard let view = view else { return nil }

        if let button = view as? UIButton, button.title(for: .normal) == title {
            return button
        }

        for subview in view.subviews {
            if let found = findButton(in: subview, withTitle: title) {
                return found
            }
        }

        return nil
    }
}

TapHelper.tapOpenButton()
EOF

